mapper.insert:
INSERT INTO group_link (
  link_url, group_name, origin, membership_state, sync_protocol_mask, created_at, updated_at
) VALUES (
  #{row.linkUrl}, #{row.groupName}, #{row.origin}, #{row.membershipState}, #{row.syncProtocolMask},
  #{row.createdAt}, #{row.updatedAt}
)
ON DUPLICATE KEY UPDATE
  deleted_at = NULL,
  group_name = COALESCE(NULLIF(TRIM(#{observedGroupName}), ''), group_name),
  membership_state = CASE WHEN membership_state = 3 THEN 3 ELSE 2 END,
  sync_protocol_mask = CASE
    WHEN sync_protocol_mask = 0 THEN #{row.syncProtocolMask}
    WHEN sync_protocol_mask = #{row.syncProtocolMask} THEN sync_protocol_mask
    ELSE 3
  END,
  updated_at = #{row.updatedAt}

mapper.update:
UPDATE group_link
SET deleted_at = NULL,
    label_id = NULL,
    import_batch_id = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.insert:
INSERT IGNORE INTO group_link (
  link_url, group_name, origin, membership_state, is_historical, is_post_control,
  created_at, updated_at
) VALUES (
  #{linkUrl}, #{groupName}, #{origin}, #{membershipState},
  COALESCE(#{isHistorical}, TRUE), COALESCE(#{isPostControl}, FALSE),
  #{createdAt}, #{updatedAt}
)

mapper.sql:
g.deleted_at IS NULL

  AND g.label_id = #{labelId}


  AND g.folder_id = #{folderId}


  AND g.folder_id IS NULL


  AND g.is_historical = 1


  AND g.is_post_control = 1


  AND g.is_historical = 1
  AND g.is_post_control = 1


  AND COALESCE(operable.availableAdminCount, 0) > 0


  AND COALESCE(operable.availableAdminCount, 0) = 0


  AND COALESCE(h.current_count, p.member_size) IS NOT NULL
  AND COALESCE(h.current_count, p.member_size) >= #{memberCountMin}


  AND COALESCE(h.current_count, p.member_size) IS NOT NULL
  AND COALESCE(h.current_count, p.member_size) <= #{memberCountMax}


  AND p.creator_continent_code = #{continentCode}


  AND p.creator_country_iso2 = #{countryIso2}


  AND p.group_created_at IS NOT NULL
  AND p.group_created_at > 0
  AND p.group_created_at <= #{nowSeconds}


  AND FLOOR((#{nowSeconds} - p.group_created_at) / 86400) >= #{ageDaysMin}


  AND FLOOR((#{nowSeconds} - p.group_created_at) / 86400) <= #{ageDaysMax}


  AND b.source_file_name LIKE CONCAT('%', #{sourceFileName}, '%')


  AND g.origin = #{origin}


  AND g.membership_state = #{membershipState}


  AND (h.id IS NULL OR h.health_status IS NULL) AND (h.is_banned IS NULL OR h.is_banned = 0)


  AND h.health_status = 1 AND (h.is_banned IS NULL OR h.is_banned = 0)


  AND h.is_banned = 1


  AND h.health_status = 2 AND (h.is_banned IS NULL OR h.is_banned = 0)


  AND h.health_status = 3 AND (h.is_banned IS NULL OR h.is_banned = 0)

mapper.select:
SELECT g.id, g.link_url AS url, COALESCE(NULLIF(TRIM(g.group_name), ''), p.wa_subject) AS groupName, p.wa_subject AS waSubject, p.group_jid AS groupJid, b.source_file_name AS sourceFileName, h.health_status AS healthStatus, h.is_banned AS banned, p.member_size AS memberSize, h.current_count AS currentCount, p.owner_phone AS ownerPhone, admins.admin AS admin, g.sync_protocol_mask AS syncProtocolMask, g.origin AS origin, g.membership_state AS membershipState, g.remark AS remark, p.avatar_url AS avatarUrl, p.last_preview_at AS lastPreviewAt, h.last_check_at AS lastCheckAt, h.last_health_error AS lastHealthError, g.created_at AS createdAt, g.is_historical AS isHistorical, g.is_post_control AS isPostControl, g.folder_id AS folderId, f.name AS folderName, CASE WHEN p.invite_code IS NULL OR TRIM(p.invite_code) = '' THEN NULL ELSE CONCAT('https://chat.whatsapp.com/', p.invite_code) END AS inviteUrl, COALESCE(operable.availableAdminCount, 0) AS availableAdminCount, p.creator_country_iso2 AS creatorCountryIso2, c.name_zh AS creatorCountryName, c.flag AS creatorCountryFlag, p.creator_continent_code AS creatorContinentCode, p.group_created_at AS groupCreatedAt, metadata_task.status AS metadataSyncStatus, metadata_task.last_success_at AS metadataSyncedAt, metadata_task.last_error_message AS metadataSyncError
WHERE
ORDER BY g.created_at DESC, g.id DESC LIMIT #{offset}, #{pageSize}

